<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Builder; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class PrecioMembresia extends Model { protected $table='precios_membresia'; protected $fillable=['tipo_membresia_id','precio','moneda','vigente_desde','vigente_hasta','motivo_cambio']; protected function casts(): array { return ['precio'=>'decimal:2','vigente_desde'=>'date','vigente_hasta'=>'date']; } public function scopeVigenteEn(Builder $query,$fecha): Builder { return $query->whereDate('vigente_desde','<=',$fecha)->where(fn($q)=>$q->whereNull('vigente_hasta')->orWhereDate('vigente_hasta','>=',$fecha)); } public function tipoMembresia(): BelongsTo { return $this->belongsTo(TipoMembresia::class); } public function membresias(): HasMany { return $this->hasMany(Membresia::class); } public function estaVigenteEn($fecha): bool { return $this->vigente_desde->lte($fecha) && ($this->vigente_hasta===null || $this->vigente_hasta->gte($fecha)); } }
